// Territory adjacency: which territories can interact with which.
//
// Loaded exactly once, into a Map, and read synchronously thereafter.
//
// This replaces readClosestPointsJSON(), which re-fetched and re-parsed the 19 MB
// closestPathsData.json once per territory during game initialisation -- 359
// fetches and ~6.8 GB of JSON.parse before the first turn. See
// docs/01-codebase-audit.md section 4.1.
//
// The data file itself is generated by tools/build-adjacency.mjs. It carries only
// what is actually read: for each uniqueId, the ordered list of neighbouring
// territory NAMES, excluding the territory itself.
//
// This module imports only its sibling data table. That is deliberate -- it sits
// at the bottom of the dependency graph, so it can be pulled into any module
// (including ones currently tangled in the import cycle) without adding an edge.

import { getManualAdditions, getManualDenials } from "./manualAdjacencyExceptions.js";

const ADJACENCY_URL = "./resources/adjacency.json";

/** @type {Map<string, string[]> | null} */
let index = null;

/** @type {Promise<Map<string, string[]>> | null} */
let loadPromise = null;

/**
 * Fetch and index the adjacency data. Safe to call any number of times and from
 * any number of places concurrently: the work happens once and every caller gets
 * the same promise.
 *
 * @param {object}   [options]
 * @param {string}   [options.url]        override the data file location
 * @param {Function} [options.fetchImpl]  override fetch (used by unit tests)
 * @returns {Promise<Map<string, string[]>>}
 */
export function loadAdjacency({ url = ADJACENCY_URL, fetchImpl } = {}) {
    if (loadPromise) {
        return loadPromise;
    }

    const doFetch = fetchImpl ?? globalThis.fetch;

    loadPromise = Promise.resolve()
        .then(() => doFetch(url))
        .then((response) => {
            if (!response || response.ok === false) {
                throw new Error(
                    `Failed to load adjacency data from ${url}` +
                        (response ? ` (HTTP ${response.status})` : "")
                );
            }
            return response.json();
        })
        .then((data) => {
            index = new Map(Object.entries(data));
            return index;
        })
        .catch((error) => {
            // Leave the module unloaded so a later attempt can retry rather than
            // being permanently poisoned by one transient failure.
            loadPromise = null;
            index = null;
            throw error;
        });

    return loadPromise;
}

/** Has the adjacency data finished loading? */
export function isAdjacencyLoaded() {
    return index !== null;
}

/**
 * The territories reachable from `uniqueId`, by territory name, nearest first.
 * Excludes the territory itself. Returns a fresh array each call, so callers can
 * mutate the result freely.
 *
 * @param {string|number} uniqueId
 * @returns {string[]}
 */
export function getReachableFrom(uniqueId) {
    if (index === null) {
        throw new Error(
            "Adjacency data has not been loaded. Await loadAdjacency() before calling getReachableFrom()."
        );
    }
    const neighbours = index.get(String(uniqueId));
    return neighbours ? neighbours.slice() : [];
}

/**
 * The territories `territoryName` can actually interact with: its geometric
 * neighbours, plus the hand-curated additions, minus the hand-curated denials.
 *
 * This is what the game means by "in range". Callers should prefer it over
 * getReachableFrom(), which is the raw geometry only.
 *
 * @param {string|number} uniqueId       the territory's uniqueId
 * @param {string}        territoryName  the territory's stable name
 * @returns {string[]}
 */
export function getInteractableFrom(uniqueId, territoryName) {
    const denied = new Set(getManualDenials(territoryName));
    const result = [];
    const seen = new Set([territoryName]);

    for (const name of getReachableFrom(uniqueId)) {
        if (!denied.has(name) && !seen.has(name)) {
            seen.add(name);
            result.push(name);
        }
    }
    for (const name of getManualAdditions(territoryName)) {
        if (!denied.has(name) && !seen.has(name)) {
            seen.add(name);
            result.push(name);
        }
    }
    return result;
}

/** Every uniqueId present in the adjacency data. */
export function adjacencyIds() {
    if (index === null) {
        throw new Error(
            "Adjacency data has not been loaded. Await loadAdjacency() before calling adjacencyIds()."
        );
    }
    return [...index.keys()];
}

/** Test seam: drop the loaded index so a spec can exercise the load path again. */
export function __resetAdjacencyForTests() {
    index = null;
    loadPromise = null;
}
